package com.gzy.qinglian;
import android.content.Context;import android.view.*;import android.widget.TextView;
import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class Hy2SettingsTest {
 private Context c(){return RuntimeEnvironment.getApplication();}
 @After public void clear(){c().getSharedPreferences("transport",0).edit().clear().commit();c().getSharedPreferences("labs",0).edit().clear().commit();TunnelService.state="disconnected";}
 @Test public void promotedDefaultDoesNotRequireOldExperimentalOptIn()throws Exception{assertTrue(Hy2Settings.performance(c()));for(boolean old:new boolean[]{false,true}){c().getSharedPreferences("labs",0).edit().putBoolean("hy2",old).commit();c().getSharedPreferences("transport",0).edit().putBoolean("accelerated",true).commit();assertTrue(Hy2Settings.saved(c()).options().getBoolean("labHy2"));}}
 @Test public void conservativeChoicePersistsAndCompatibilityNeverRequestsHighPerformance()throws Exception{assertTrue(Hy2Settings.savePerformance(c(),false));assertFalse(Hy2Settings.performance(c()));c().getSharedPreferences("transport",0).edit().putBoolean("accelerated",true).commit();assertFalse(Hy2Settings.saved(c()).options().getBoolean("labHy2"));assertTrue(Hy2Settings.savePerformance(c(),true));c().getSharedPreferences("transport",0).edit().putBoolean("accelerated",false).commit();assertFalse(Hy2Settings.saved(c()).options().getBoolean("labHy2"));}
 @Test public void bothServerAcknowledgmentAndMatchingNativeParametersAreRequired()throws Exception{JSONObject high=new JSONObject().put("labHy2",true).put("acceleration",new JSONObject().put("node",new JSONObject().put("hy2Performance","aggressive-v1")));Hy2Settings.confirm(new Hy2Settings.Selection(true,true),high);assertThrows(Exception.class,()->Hy2Settings.confirm(new Hy2Settings.Selection(true,false),high));high.put("labHy2",false);assertThrows(Exception.class,()->Hy2Settings.confirm(new Hy2Settings.Selection(true,true),high));high.getJSONObject("acceleration").getJSONObject("node").remove("hy2Performance");Hy2Settings.confirm(new Hy2Settings.Selection(true,false),high);Hy2Settings.confirm(new Hy2Settings.Selection(false,true),new JSONObject());}
 @Test public void activeLeaseAndRecoveryIgnorePendingUiSelection()throws Exception{var control=Robolectric.buildService(TunnelService.class).create();try{TunnelService s=control.get();Hy2Settings.Selection running=new Hy2Settings.Selection(true,true);ReflectionHelpers.setField(s,"selectedProfile",running);TunnelService.state="connected";Hy2Settings.savePerformance(c(),false);c().getSharedPreferences("transport",0).edit().putBoolean("accelerated",false).commit();assertSame(running,Hy2Settings.effective(c()));assertTrue(Hy2Settings.effective(c()).options().getBoolean("labHy2"));TunnelService.state="reconnecting";assertSame(running,Hy2Settings.effective(c()));assertFalse(Hy2Settings.saved(c()).options().getBoolean("labHy2"));ReflectionHelpers.setField(s,"cancelled",true);assertFalse(Hy2Settings.effective(c()).options().getBoolean("labHy2"));}finally{control.destroy();}}
 @Test public void conservativeToPerformanceSelectionAlsoWaitsForReconnect()throws Exception{var control=Robolectric.buildService(TunnelService.class).create();try{TunnelService s=control.get();Hy2Settings.Selection running=new Hy2Settings.Selection(true,false);ReflectionHelpers.setField(s,"selectedProfile",running);TunnelService.state="connected";c().getSharedPreferences("transport",0).edit().putBoolean("accelerated",true).commit();Hy2Settings.savePerformance(c(),true);assertFalse(Hy2Settings.effective(c()).options().getBoolean("labHy2"));assertTrue(Hy2Settings.saved(c()).options().getBoolean("labHy2"));}finally{control.destroy();}}
 @Test public void productionConnectionPageOffersPerformanceAndConservativeModes(){try(var controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=controller.get();TextView conservative=find(a.getWindow().getDecorView(),"保守");assertNotNull(conservative);assertNotNull(find(a.getWindow().getDecorView(),"高性能"));conservative.performClick();assertFalse(Hy2Settings.performance(a));}}
 private TextView find(View v,String text){if(v instanceof TextView&&text.equals(((TextView)v).getText().toString()))return (TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView found=find(g.getChildAt(i),text);if(found!=null)return found;}}return null;}
}
